{
  "story": "AdaBoost increases the weight of misclassified training examples so subsequent weak learners focus on hard cases.",
  "aha": {
    "stateId": "step-boost",
    "observation": "The misclassified example's weight is scaled up significantly by the exponential error factor."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "AdaBoost Step",
      "options": [
        "Initialize",
        "Predict",
        "Evaluate",
        "Boost"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "AdaBoost Weights Update",
        "regions": [
          {
            "id": "ex1",
            "label": "Example A (Correct)",
            "kind": "cell",
            "values": ["x=1", "y=+1", "w=0.25"]
          },
          {
            "id": "ex2",
            "label": "Example B (Wrong)",
            "kind": "cell",
            "values": ["x=2", "y=-1", "w=0.25"]
          },
          {
            "id": "ex3",
            "label": "Example C (Correct)",
            "kind": "cell",
            "values": ["x=3", "y=+1", "w=0.25"]
          },
          {
            "id": "ex4",
            "label": "Example D (Correct)",
            "kind": "cell",
            "values": ["x=4", "y=-1", "w=0.25"]
          }
        ],
        "states": [
          {
            "id": "step-init",
            "label": "Initialize",
            "short": "Init",
            "sentence": "All training examples start with equal uniform weights.",
            "why": "Uniform distribution gives every sample an equal initial vote.",
            "active": ["ex1", "ex2", "ex3", "ex4"],
            "calloutRegion": "ex1",
            "readouts": [
              {
                "id": "r1",
                "label": "Total Weight",
                "value": "1.00"
              },
              {
                "id": "r2",
                "label": "Error Rate",
                "value": "0.00"
              }
            ]
          },
          {
            "id": "step-pred",
            "label": "Predict",
            "short": "Predict",
            "sentence": "The weak learner classifies the four examples.",
            "why": "Testing current model hypothesis against labels.",
            "active": ["ex1", "ex2", "ex3", "ex4"],
            "calloutRegion": "ex2",
            "readouts": [
              {
                "id": "r1",
                "label": "Correct",
                "value": "3"
              },
              {
                "id": "r2",
                "label": "Mistakes",
                "value": "1"
              }
            ]
          },
          {
            "id": "step-eval",
            "label": "Evaluate",
            "short": "Eval",
            "sentence": "Example B is incorrectly predicted by the learner.",
            "why": "Identifying the error source to compute stage value alpha.",
            "active": ["ex2"],
            "calloutRegion": "ex2",
            "readouts": [
              {
                "id": "r1",
                "label": "Error epsilon",
                "value": "0.25"
              },
              {
                "id": "r2",
                "label": "Model alpha",
                "value": "0.69"
              }
            ]
          },
          {
            "id": "step-boost",
            "label": "Boost",
            "short": "Boost",
            "sentence": "The wrong example's weight increases while correct ones shrink.",
            "why": "Exponential multiplier amplifies penalty on missed items.",
            "active": ["ex2"],
            "calloutRegion": "ex2",
            "readouts": [
              {
                "id": "r1",
                "label": "New Weight B",
                "value": "0.50"
              },
              {
                "id": "r2",
                "label": "Normalized Sum",
                "value": "1.00"
              }
            ]
          }
        ]
      }
    ]
  }
}
